// Applies the baseline migration to Supabase and records it in
// _prisma_migrations, WITHOUT prisma migrate reset and WITHOUT dropping data.
//
// Why not `prisma migrate deploy` here: Prisma CLI's classic engine hangs on
// PgBouncer transaction-mode pooling (Supabase pooler port 6543). node-postgres
// speaks the simple query protocol, which works fine through the pooler. The
// migration is first executed (idempotent CREATE ... IF NOT EXISTS SQL
// generated by `prisma migrate diff --from-empty`), then registered in
// `_prisma_migrations` with the same checksum format the Prisma CLI uses, so
// `prisma migrate status` and future `migrate deploy` runs stay consistent.
// Credentials are read from .env.local and never printed.
import { createHash } from 'node:crypto';
import pg from 'pg';
import { readFileSync } from 'node:fs';

const MIGRATION_NAME = '0001_init';
const migrationFile = `prisma/migrations/${MIGRATION_NAME}/migration.sql`;
const sql = readFileSync(migrationFile, 'utf8');

const line = readFileSync('.env.local', 'utf8')
  .split(/\r?\n/)
  .find((l) => l.startsWith('DATABASE_URL='));
if (!line) {
  console.error('DATABASE_URL not found in .env.local');
  process.exit(1);
}
const connectionString = line.slice('DATABASE_URL='.length).trim().replace(/^["']|["']$/g, '');
const u = new URL(connectionString);
const client = new pg.Client({
  host: u.hostname,
  port: Number(u.port) || 5432,
  user: decodeURIComponent(u.username),
  password: decodeURIComponent(u.password),
  database: u.pathname.replace(/^\//, '') || 'postgres',
  ssl: { rejectUnauthorized: false },
});

// Prisma records a base64-encoded SHA-384 digest of the migration file as the
// checksum (64 chars, matching the VARCHAR(64) column).
const checksum = createHash('sha384').update(sql, 'utf8').digest('base64');

try {
  await client.connect();

  // Ensure the Prisma migration bookkeeping table exists (canonical DDL used
  // by the Prisma CLI). CREATE IF NOT EXISTS — never destructive.
  await client.query(`CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
  id VARCHAR(36) PRIMARY KEY NOT NULL,
  checksum VARCHAR(64) NOT NULL,
  finished_at TIMESTAMPTZ,
  migration_name VARCHAR(255) NOT NULL,
  logs TEXT,
  rolled_back_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ NOT NULL,
  applied_steps_count INTEGER NOT NULL DEFAULT 0
)`);

  // Already applied? (idempotent re-runs must be a no-op)
  const existing = await client.query(
    'SELECT finished_at FROM "_prisma_migrations" WHERE migration_name = $1',
    [MIGRATION_NAME],
  );
  if (existing.rows.length > 0) {
    console.log(`Migration ${MIGRATION_NAME} already recorded — nothing to do.`);
  } else {
    console.log(`Applying baseline migration ${MIGRATION_NAME} (${sql.length} bytes)...`);
    try {
      await client.query(sql);
    } catch (error) {
      // Idempotent re-run: schema objects from a previous (partially recorded)
      // attempt already exist. Only "already exists" is tolerated; anything
      // else is a real failure.
      if (!/already exists/.test(error.message)) throw error;
      console.log('Schema objects already exist — skipping DDL, recording migration only.');
    }
    await client.query(
      `INSERT INTO "_prisma_migrations"
         (id, checksum, finished_at, migration_name, logs, applied_steps_count, started_at)
       SELECT gen_random_uuid(), $1::text, now(), $2::text, NULL, 1, now()
       WHERE NOT EXISTS (
         SELECT 1 FROM "_prisma_migrations" WHERE migration_name = $2::text
       )`,
      [checksum, MIGRATION_NAME],
    );
    console.log(`Applied and recorded ${MIGRATION_NAME}.`);
  }

  const status = await client.query(
    `SELECT migration_name, finished_at, applied_steps_count
       FROM "_prisma_migrations" ORDER BY started_at`,
  );
  console.log('Migration history:');
  for (const row of status.rows) {
    console.log(`  ${row.migration_name} — applied_steps: ${row.applied_steps_count}`);
  }
  const tables = await client.query(
    `SELECT count(*)::int AS count FROM information_schema.tables
     WHERE table_schema = 'public' AND table_type = 'BASE TABLE'`,
  );
  console.log('Public tables after migration:', tables.rows[0].count);
  console.log('BASELINE MIGRATION: PASS');
} catch (error) {
  console.error('Baseline migration FAILED:', error.message);
  process.exitCode = 1;
} finally {
  await client.end().catch(() => {});
}
